mapper.select:
/* USE : NaverPlaceEasyLinkMapper.getNaverPlaceUserList */ SELECT A.HQ_OFFICE_CD , C.HQ_OFFICE_NM , A.STORE_CD , D.STORE_NM , D.SYS_STAT_FG , D.BIZ_NO , A.IN_TYPE , A.UNIQUE_ID , TO_CHAR(TO_DATE(A.LAST_RESPONSE_DT, 'YYYYMMDDHH24MISS'), 'YYYY-MM-DD HH24:MI:SS') AS LAST_RESPONSE_DT , A.MP_NO , A.ETC01 , A.ETC02 , A.ETC03 , A.ETC04 , A.ETC05 , A.ETC06 , A.ETC07 , A.ETC08 , A.ETC09 , A.ETC10 , A.NAVER_STORE_NM , A.NAVER_PLACE_ID , TO_CHAR(TO_DATE(A.NAVER_LINK_DT, 'YYYYMMDDHH24MISS'), 'YYYY-MM-DD HH24:MI:SS') AS NAVER_LINK_DT , TO_CHAR(TO_DATE(B.LAST_RESPONSE_DT, 'YYYYMMDDHH24MISS'), 'YYYY-MM-DD HH24:MI:SS') AS AGREEMENT_LAST_RESPONSE_DT , B.AGREEMENT_TYPE , A.ORDER_UNIQUE_ID , A.ORDER_BUSINESS_ID , A.ORDER_CHANNEL_SERVICE_ID_TABLE , A.ORDER_CHANNEL_SERVICE_ID_PICKUP FROM TB_CM_NAVER_LINK A , TB_CM_NAVER_LINK_AGREEMENT B , TB_HQ_OFFICE C , TB_MS_STORE D WHERE A.HQ_OFFICE_CD = B.HQ_OFFICE_CD(+) AND A.STORE_CD = B.STORE_CD(+) AND A.HQ_OFFICE_CD = C.HQ_OFFICE_CD AND A.STORE_CD = D.STORE_CD
AND A.IN_TYPE = #{inType}
AND D.BIZ_NO LIKE '%'||#{bizNo}||'%'
ORDER BY A.HQ_OFFICE_CD, A.STORE_CD

mapper.delete:
/* USE : NaverPlaceEasyLinkMapper.deleteNaverPlaceEasyLinkExcelAll */
DELETE
FROM    TB_TMP_EXCEL_NAVER_LINK
WHERE   SESSION_ID = #{sessionId}

/* USE : NaverPlaceEasyLinkMapper.deleteNaverPlaceEasyLinkExcel */
DELETE
FROM    TB_TMP_EXCEL_NAVER_LINK
WHERE   SESSION_ID = #{sessionId}
AND     SEQ = #{seq}

mapper.select:
/* USE : NaverPlaceEasyLinkMapper.getStoreByBizNo */
SELECT  HQ_OFFICE_CD
,       STORE_CD
FROM    TB_MS_STORE
WHERE   BIZ_NO = #{businessNumber}
AND     ROWNUM = 1

/* USE : NaverPlaceEasyLinkMapper.getNaverLinkRegCnt */
SELECT  COUNT(*)
FROM    TB_CM_NAVER_LINK
WHERE   HQ_OFFICE_CD = #{hqOfficeCd}
AND     STORE_CD = #{storeCd}
AND     NAVER_PLACE_ID IS NOT NULL
AND     IN_TYPE IS NOT NULL

/* USE : NaverPlaceEasyLinkMapper.getStoreNm */
SELECT  STORE_NM
FROM    TB_MS_STORE
WHERE   STORE_CD = #{storeCd}
